// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Anadolu mutfak mirası, yöresel yemekler, coğrafi işaretli lezzetler ve içecek kültürü tarihi (kahve, çay, boza, şerbet, tarhana, zeytinyağı, pişirme kapları) (zor).
const ozCulture15Zor = <(String, String, List<String>, String)>[
  ('1554 yılında İstanbul Tahtakale\'de ilk kahvehaneleri açarak şehirde yeni bir sosyalleşme mekânının doğmasına öncülük eden girişimciler kimlerdir?', 'Halepli Hakem ve Şamlı Şems', ['Bursalı İskender ve Karagöz', 'Vefalı Hacı Sadık ve Mahmut', 'Yemenli Ömer ve Mısırlı Hasan'], 'Tarihçi Peçevî\'nin aktardığına göre Halepli Hakem ile Şamlı Şems, Tahtakale\'de açtıkları dükkânlarla İstanbul\'da kahvehane geleneğini başlatmıştır.'),
  ('Mırra pişirmek ve sıcak tutarak misafirlere sunmak için kullanılan, gagalı ibrik biçimindeki geleneksel sarı pirinç veya bakır kaba ne ad verilir?', 'Gümgüm', ['Lenger', 'Kevgir', 'Sini'], 'Şanlıurfa ve Mardin çevresinde mırra, uzun emzikli ve kapaklı özel ibrik olan gümgüm içinde demlenip tazelenir.'),
  ('Rize ve çevresinde turunçgil ile çay yetiştirilebileceğini 1917 tarihli bilimsel inceleme gezisi raporuyla ilk kez ortaya koyan Halkalı Ziraat Mektebi müderrisi kimdir?', 'Ali Rıza Erten', ['Ahmet Vefik Paşa', 'Derviş Mehmed Paşa', 'Suphi Paşa'], 'Ali Rıza Erten, Doğu Karadeniz\'in yağış ve toprak yapısını Batum ile karşılaştırarak bölgede çay tarımının elverişli olduğunu raporlaştırmıştır.'),
  ('Osmanlı döneminde bozahanelerin zaman zaman sıkı denetime tabi tutulmasına ya da kapatılmasına yol açan \'ekşi boza\' (Tatar bozası) ile \'tatlı boza\' arasındaki temel fark nedir?', 'Fermantasyon süresinin uzamasıyla alkol oranının sarhoş edici düzeye çıkması', ['Ekşi bozada darı yerine acı badem ve pelin otu kullanılması', 'Tatlı bozanın yalnızca keçi sütü kaynatılarak mayasız üretilmesi', 'Ekşi bozanın içine koruyucu olarak kaya tuzu ve sirke eklenmesi'], 'Şeyhülislam fetvalarında tatlı boza helal sayılırken, fazla bekletilip alkol oranı yükselen ekşi boza sarhoşluk verdiği gerekçesiyle yasaklanmıştır.'),
  ('Kırklareli yöresine ait coğrafi işaretli bir içecek olan \'hardaliye\' üretilirken üzüm şırasının alkole dönüşmesini engelleyen temel bileşen hangisidir?', 'Kırılmış siyah hardal tohumu ve vişne yaprağı', ['Kavrulmuş arpa unu ve kaya tuzu', 'Nohut mayası ve kurutulmuş incir', 'Ezilmiş çam fıstığı ve damla sakızı'], 'Trakya\'nın geleneksel içeceği hardaliyede olgun koyu renkli üzümler vişne yaprağı ve ezilmiş siyah hardal tohumuyla fıçılara basılır; hardaldaki uçucu yağlar alkol fermantasyonunu durdurur.'),
  ('Mevlevi mutfak kültüründe önemli yeri olan, bal ve elma/üzüm sirkesinin nane aromasıyla dengelenerek suyla inceltilmesiyle hazırlanan tarihi şerbet hangisidir?', 'Sirkencübin', ['Demirhindi', 'Hardaliye', 'Somata'], 'Farsça \'sirke\' ve \'engübin\' (bal) kelimelerinden türeyen sirkencübin, Mevlânâ\'nın eserlerinde de sıkça anılan tatlı-ekşi dengeli geleneksel bir şerbettir.'),
  ('Bozcaada ve Ege kıyılarında acı ile tatlı badem içinin dövülüp şeker şurubu ve gül/çiçek suyuyla kaynatılması sonucu elde edilen konsantre badem şerbetine ne ad verilir?', 'Somata', ['Sübye', 'Şıra', 'Mırra'], 'Somata (sübye ile akraba ancak badem esaslı), dövülmüş badem özünün şurupla yoğunlaştırılmasıyla hazırlanır ve sunumda soğuk suyla açılarak içilir.'),
  ('Elazığ mutfak kültüründe çedene (kavrulmuş kenevir tohumu ya da yöredeki kullanımıyla menengiç) ezmesinin sütle pişirilmesiyle hazırlanan yöresel kahve hangi adla tescillenmiştir?', 'Harput çedene kahvesi', ['Palu mırra kahvesi', 'Hazar süvari kahvesi', 'Keban kenger kahvesi'], 'Elazığ\'da \'çedene\' adıyla anılan kavrulmuş menengiç meyvelerinin dövülerek pişirilmesiyle elde edilen Harput çedene kahvesi coğrafi işaretli bir değerdir.'),
  ('Eskişehir ve Kırım Tatar mutfak geleneğinde pişen sade Türk kahvesinin içerisine sıcak süt veya kaymak eklenerek büyük fincanlarda sunulmasına ne ad verilir?', 'Tatar kahvesi', ['Yörük kahvesi', 'Kervan kahvesi', 'Saray mırra kahvesi'], 'Kırım göçmeni Tatarların yaşattığı gelenekte, köpüklü kahveye kaymak ya da süt katılarak hazırlanan yumuşak içimli kahveye sütlü Tatar kahvesi denir.'),
  ('Antalya ve Alanya\'dan Doğu Karadeniz\'e, oradan da 1924 yılında çıkarılan 407 sayılı kanunla Rize\'de çay ve narenciye yetiştiriciliğine zemin hazırlayan süreçte hangi tarihsel ekonomik kırılma etkili olmuştur?', 'Birinci Dünya Savaşı ve Rus Devrimi sonrasında Batum\'daki iş gücü ve ticaret yollarının kapanmasıyla Rize\'de geçim sıkıntısı yaşanması', ['İpek böcekçiliğinin Karadeniz kıyılarında aşırı kuraklık yüzünden tamamen sona ermesi', 'Osmanlı dış borçlarının tamamının kuru çay ihracatıyla ödenmesi şartının getirilmesi', 'Karadeniz\'de hamsi avcılığının on yıl süreyle uluslararası anlaşmayla yasaklanması'], 'Cumhuriyet\'in ilk yıllarında Batum sınırının kapanmasıyla gurbet gelirini kaybeden Rize halkına kalıcı bir tarımsal gelir sağlamak için 1924\'te 407 sayılı kanun çıkarılmıştır.'),
  ('Gaziantep ve Kilis yöresinde üzüm bağlarından toplanan olgun meyvelerin sıkılıp kaynatılmadan önce berraklaşması için kullanılan beyaz \'şıra toprağı\' kimyasal olarak hangi özelliğiyle etki gösterir?', 'Kalsiyum karbonat içeriğiyle üzüm suyunun asitliğini düşürüp tortuyu dibe çökertmesi', ['Demir oksit yardımıyla şırayı anında koyu kırmızı şaraba dönüştürmesi', 'Yüksek tuz oranıyla üzüm şekerini kristalleştirip dondurması', 'Kükürt gazı çıkararak şıranın hacmini iki katına yükseltmesi'], 'Pekmez veya şıra toprağı (%50-90 kireç/kalsiyum karbonat içerir), şıradaki tartarik ve malik asidi nötralize ederek bulanıklık veren pektin ve proteinlerin çökelmesini sağlar.'),
  ('Edirne ve Osmanlı saray geleneğinde badem ezmesi, misk, amber, tarçın ve karanfilin şekerle kaynatılıp dondurulmasıyla elde edilen, sıcak suda eritilerek içilen kalıp içecek malzemesi hangisidir?', 'Deva-i misk ve şerbet akidesi', ['Tuzlu kurut topağı', 'Kavrulmuş tarhana cipsi', 'Ekşi pestil sarması'], 'Saray ve Edirne helvahane kültüründe kokulu baharatlarla sertleştirilen şerbet kalıpları veya akideler, yolculukta ve konaklarda sıcak/soğuk suda eritilerek şerbete dönüştürülürdü.'),
  ('Osmanlı döneminde kahvenin soğumasını önlemek ve misafire el yakmadan zarifçe sunmak amacıyla kulpsuz porselen fincanların içine oturtulduğu metal veya gümüş yuvalara ne ad verilirdi?', 'Zarf', ['Hokka', 'Sahan', 'Kاشık'], 'Kulpsuz fincanlar telkari gümüş, altın, pirinç veya bağadan yapılan ince işçilikli \'fincan zarfı\' içine yerleştirilerek ikram edilirdi.'),
  ('Bursa\'nın Uludağ eteklerinden doğan kaynak suları ve meyve bahçeleriyle gelişen şerbetçilik geleneğinde, Osmanlı sarayına kar ve buz gönderen görevli zümreye ne denirdi?', 'Karcıyan ve buzcuyan', ['Bostancıyan', 'Lağımcıyan', 'Humbaracıyan'], 'Yaz aylarında saray şerbetlerini soğutmak için Uludağ\'daki kar kuyularından katırlarla ve gemilerle İstanbul\'a kar taşıyan teşkilata karcıyan/buzcuyan denilirdi.'),
  ('Osmanlı sarayında yeniçerilerin üç ayda bir aldıkları ulufe töreni veya sadrazam ziyareti sırasında kendilerine sunulan şerbet kâselerini içmeleri siyasi açıdan neyin göstergesiydi?', 'Padişaha ve yönetime duyulan memnuniyet ile itaatin simgesi', ['Ordunun ertesi sabah sefere çıkacağının kesin ilanı', 'Acemi oğlanların emekliye ayrıldığının resmi belgesi', 'Saray mutfağındaki aşçıların görevden alındığının işareti'], 'Osmanlı protokolünde çorba ve şerbet ikramının kabul edilip içilmesi hoşnutluk ve bağlılık anlamına gelir; kazan kaldırmak veya ikramı reddetmek ise isyan işareti sayılırdı.'),
  ('Konya ve Mevlevi mutfağında koruk, nar, demirhindi veya gül şerbetlerinin yanı sıra yemek ortasında ya da sonunda içilen naneli ve kuru üzümlü serinletici soğuk ayran aşı benzeri içeceklere eşlik eden \'ekşi\' geleneğinde sumak şerbeti nasıl elde edilir?', 'Tane sumağın ılık suda bekletilip ovulmadan tülbentten süzülmesiyle', ['Sumak yapraklarının zeytinyağında kavrulup sütle karıştırılmasıyla', 'Toz sumağın şekerle karamelize edilip dondurulmasıyla', 'Sumak köklerinin taş fırında yakılıp külünün suya katılmasıyla'], 'Tane sumak ılık suda dinlendirildiğinde kabuğundaki sitrik ve malik asit suya geçer; acı tanenlerin çıkmaması için taneler ezilmeden süzülür.'),
  ('Karadeniz\'den Doğu Anadolu\'ya uzanan güzergâhta, özellikle Erzurum kahvehanelerinde demli çayın yanında limon dilimiyle sunulan ve çayın rengini açık sarıya çeviren kimyasal etki neye dayanır?', 'Limondaki sitrik asidin çaydaki tearubigin pigmentlerinin pH değerini düşürmesine', ['Limon kabuğundaki yağın çaydaki suyu buharlaştırmasına', 'C vitamininin çay yapraklarını bardağın dibine yapıştırmasına', 'Şeker ile limonun birleşerek çayı mayalamasına'], 'Siyah çaya kızıl-kahve rengini veren tearubiginler pH indikatörü gibi davranır; limon suyu eklendiğinde asidik ortamda iyonlaşma azalır ve çayın rengi açılır.'),
  ('Osmanlı evlerinde kavrulmuş sıcak kahve çekirdeklerinin öğütülmeden önce terlememesi ve kokusunu kaybetmemesi için aktarıldığı kapaklı ahşap gerece ne ad verilirdi?', 'Kahve soğutucusu', ['Ekmek teknesi', 'Hamur tahtası', 'Yayık fıçısı'], 'Tavadan çıkan kızgın çekirdekler oyma ceviz ya da şimşir ağacından yapılan kahve soğutucusunda sallanarak ılıtılır, ardından değirmene konulurdu.'),
  ('Pastırma çemenine karakteristik keskin kokusunu ve bağlayıcı macun kıvamını veren baklagiller familyasından otsu bitki tohumu hangisidir?', 'Buy otu (çemen otu) tohumu', ['Kişniş meyvesi tohumu', 'Yabani hardal tanesi', 'Siyah çörek otu'], 'Trigonella foenum-graecum bilimsel adlı buy (çemen) otunun öğütülmüş tohumları suyla birleştiğinde müsilajlı bir macun oluşturarak sarımsak ve biberi et yüzeyine bağlar.'),
  ('Sığır gövdesinin sırt ve bel bölgesinden çıkarılan, sinirsiz ve mermerimsi yağ dağılımıyla en yumuşak ve değerli kabul edilen pastırma çeşidi hangisidir?', 'Kuşgömü ve sırt', ['İncik ve gerdan', 'Kavram ve döş', 'Kuyruk ve paça'], 'Pastırmacılıkta hayvanın hareket etmeyen sırt/bonfile çevresinden elde edilen kuşgömü ve sırt pastırması en makbul kısımlar arasında yer alır.'),
  ('Tokat\'ın Zile ilçesine özgü beyaz renkli ve ekmeğe sürülebilen katı kıvamlı \'Zile pekmezi\' üretilirken üzüm pekmezinin rengini açıp krema dokusu kazandıran işlem nedir?', 'Soğutulan pekmeze yumurta akı ve pekmez mayası katılarak tahta küreklerle uzun süre çırpılması', ['Kaynayan üzüm şırasının içine manda kaymağı ve buğday unu eklenmesi', 'Pekmezin kar kuyularında bir ay bekletilerek buz kristallerinden ayrıştırılması', 'Beyaz üzümlerin kabuklarının kireç suyunda haşlanıp güneşte ağartılması'], 'Çalma pekmez olarak da bilinen Zile pekmezinde koyu üzüm pekmezi yumurta akı ile hava yedirilerek saatlerce dövülür (çalınır) ve sedefimsi beyaz-krem rengine kavuşur.'),
  ('Trakya ve Ege göçmen mutfaklarında kışlık olarak elde yuvarlanarak hazırlanan geleneksel \'kuskus\', hangi malzemelerin ahşap teknede sabırla birbirine yedirilmesiyle tanecik halini alır?', 'İnce bulgur veya irmik çekirdeğinin süt ve yumurtalı un serpintisiyle el altında döndürülerek kaplanması', ['Haşlanmış patates püresinin mısır nişastasıyla kıyma makinesinden çekilmesi', 'Pirinç tanelerinin pekmezli suda şişirilip susamla kavrulması', 'Nohut ununun zeytinyağıyla yoğrulup rende deliklerinden geçirilmesi'], 'Ev yapımı kuskusta en ince bulgur (düğü) başlangıç çekirdeği olarak kullanılır; üzerine yumurta-süt karışımı çırpılıp un serpildikçe avuç hareketiyle küresel boncuklar büyütülür.'),
  ('Kars, Ardahan ve Artvin yörelerinde sonbahar sonunda kesilen kaz veya sığır etlerinin kaya tuzuyla ovulup ayazda ve rüzgârda kurutulmasıyla elde edilen geleneksel kışlık ete ne ad verilir?', 'Kakaç', ['Çemen', 'Söğüş', 'Tantuni'], 'Eski Türkçeden beri kurutulmuş et anlamında yaşayan \'kakaç\', Kuzeydoğu Anadolu\'da tuzlanıp kış ayazında kurutulan kaz ve sığır etleri için kullanılır.'),
  ('Doğu Anadolu ve Karadeniz yaylalarında kavrulmuş arpa veya buğday ununun kışlık olarak saklanıp tüketileceği zaman tereyağı ve şeker/pekmezle karıştırılmasıyla hazırlanan pratik enerji yiyeceği hangisidir?', 'Kavut', ['Sübye', 'Zerde', 'Şöbiyet'], 'Kaşgarlı Mahmud\'un Divânu Lügâti\'t-Türk eserinde de geçen kavut, kavrulmuş tahıl ununun yağ ve tatlıyla yoğrulup yenildiği bin yıllık bir Türk azığıdır.'),
  ('Aydın\'da yetişen coğrafi işaretli Sarılop incirlerinin dalında kendiliğinden buruşup yarı kuruyarak toprağa düşmesinden sonra toplanıp kerevetlerde tam kurutulması sürecinde incirin daldaki bu yarı kuru evresine ne denir?', 'Buruşuk', ['Yeşil ilek meyvesi', 'Ham koruk salkımı', 'Taze çağla çekirdeği'], 'Kurutmalık Sarılop inciri yaşken koparılmaz; ağaç üzerinde olgunlaşıp suyunu kaybederek buruşur (uyuşur/erir) ve kendiliğinden düştüğünde toplanıp sergilere serilir.'),
  ('Aydın incir bahçelerinde meyve tutumunu ve kaliteli kuru incir oluşumunu sağlamak için haziran ayında ağaçlara yabani erkek incir meyvelerinin asılması işlemine ne ad verilir?', 'İlekleme', ['Aşılama', 'Budama', 'Çapalama'], 'Sarılop dişi incirlerinin döllenmesi için erkek incir (ilek) meyveleri içindeki incir arıcığının polen taşıması gerekir; bu geleneksel tarımsal işleme ilekleme denir.'),
  ('İlkbaharda Karadeniz\'e dönerken tüm yağını kaybetmiş zayıf uskumru balıklarının tuzlanıp iplere dizilerek açık havada rüzgârla kurutulmasıyla elde edilen geleneksel saklama ürünü hangisidir?', 'Çiroz', ['Lakerda', 'Likapa', 'Kuymak'], 'Yağlı balık kurutulursa acılaşacağı için özellikle yumurta dökmüş yağsız bahar uskumruları seçilir ve güneş-rüzgârda kurutularak çiroz elde edilir.'),
  ('Konya\'nın Beyşehir ve Derebucak yöresinde kabuğu soyulup kırılmış buğday (göce) ile ayranın bakır kazanda pişirilip ceviz yaprakları üzerinde yassı halkalar halinde kurutulduğu kışlık ürün hangisidir?', 'Göce (Beyşehir) tarhanası', ['Kastamonu yaş tarhanası', 'Trakya ak tarhanası', 'Edirne ciğer sarması'], 'Göce tarhanası Maraş tarhanasına akraba bir teknikle kırık dövme ve yayık ayranından pişirilip yassı sıkımlar halinde kurutulur; kışın ateşte közlenerek ya da çorba yapılarak yenir.'),
  ('Hatay ve Mersin yöresinde kışlık yapılan çıtır kabak tatlısı, ceviz reçeli veya patlıcan reçelinde ham meyve/sebze dilimlerinin şerbete atılmadan önce bekletildiği duru çözelti hangisidir?', 'Sönmüş kireç kaymağı suyu', ['Tuzlu peynir altı suyu', 'Kızılcık ekşisi şırası', 'Arpa maltı sirkesi'], 'Kireç suyundaki kalsiyum iyonları bitki hücre duvarındaki pektinle kalsiyum pektat bağları kurar; böylece kabak dıştan çıtır kabuk bağlarken içi şeffaf ve sulu kalır.'),
  ('Konya, Karaman ve Niğde (Obruk ve Divle) çevresinde tulum peynirleri ile kışlık gıdaların olgunlaştırıldığı derin karstik mağaraların mikroiklim özelliği nedir?', 'Yaz-kış 4-6 derece civarında serin kalması ve yüksek bağıl nemle kendine has küf florası barındırması', ['İçerideki sıcaklığın 40 dereceye ulaşarak peynirin yağını eritmesi', 'Tamamen kuru çöl havasına sahip olup peyniri iki günde taşlaştırması', 'Tabanından çıkan tuzlu sıcak kaplıca sularıyla tulumları yıkaması'], 'Karaman Divle Obruğu ve Konya obruk mağaraları yıl boyu yaklaşık 4-5 °C sıcaklık ve %80-85 nem sağlayarak deri tulumlardaki peynirlerin eşsiz biçimde olgunlaşmasına olanak tanır.'),
  ('Giresun ve Ordu yöresinde ilkbahar sonu ve yaz başında toplanan taze fasulyelerin haşlanıp güneşte kurutulmasıyla elde edilen ve kışın mısır kırması ya da bulgurla pişirilen kurutulmuş fasulyeye ne denir?', 'Fırın kurusu veya kaba (puçuko) kurusu', ['Taze börülce filizi', 'Sütlü bakla ezmesi', 'Közlenmiş kapya dilimi'], 'Doğu Karadeniz\'de kılçıksız taze fasulyeler hafif haşlanıp kurutularak \'puçuko / fırın kurusu fasulye\' adıyla kışlık çorba ve sulu yemeklik olarak saklanır.'),
  ('Sinop ve Kastamonu mutfağında sonbahar yağmurlarından sonra çam ve köknar ormanlarından toplanan \'kanlıca mantarı\' (çıntar / melki), kışa saklanmak üzere geleneksel olarak nasıl işlenir?', 'Haşlanıp bol kaya tuzuyla bidon ve küplere salamura olarak basılmasıyla', ['Şeker şurubunda kaynatılıp reçel kavanozlarına doldurulmasıyla', 'Çiğ haldeyken unla yoğrulup tarhana hamuruna katılmasıyla', 'Süt kaymağı içinde bekletilip dondurulmadan rafta tutulmasıyla'], 'Batı Karadeniz\'de kanlıca mantarı bol çıktığı sonbahar haftalarında temizlenip hafif haşlanır ve kaya tuzuyla salamura kurularak kışın tuzu alınıp kavurması veya ekşilisi yapılır.'),
  ('Gaziantep\'te kışlık yuvalama yemeği için pirinç unu, yağsız çiğ köftelik kıyma ve irmikten nohut büyüklüğünde yuvarlanan binlerce minik köfte saklanmadan önce hangi işleme tabi tutulur?', 'Buharda (süzgeçte) haşlanıp temiz bez üzerinde kurutularak sertleştirilir', ['Pekmez şırasına batırılıp cevizlerle birlikte ipe dizilir', 'Sarımsaklı çemen macunuyla kaplanıp güneşte bekletilir', 'Üzüm sirkesi ve kaya tuzu dolu küplere çiğ olarak atılır'], 'Bayram sabahlarının baş yemeği olan Antep yuvalamasının minik köfteleri avuç içinde yuvarlandıktan sonra buharda terletilir (haşlanır) ve kurutularak saklanır.'),
  ('Burdur, Isparta ve Afyon yöresinde kışlık haşlanmış nohut ve buğdayla birlikte kurutulmuş elma, armut veya erik dilimlerine ne ad verilir?', 'Kak (Hoşaflık meyve kurusu)', ['Posa (Üzüm cibresi)', 'Kavut (Kavruk un)', 'Çemen (Buy macunu)'], 'Batı Toroslar, Göller Yöresi ve Denizli-Muğla hattında dilimlenerek güneşte kurutulmuş elma, armut, şeftali ve eriğe \'kak\' (elma kakı, erik kakı) denir; kışın hoşafı yapılır.'),
  ('Ev yapımı sebze konservelerinde (özellikle yeşil fasulye, bezelye, biber gibi düşük asitli gıdalarda) yetersiz ısıl işlem uygulandığında oksijensiz ortamda toksin üreterek ağır gıda zehirlenmesine yol açabilen bakteri hangisidir?', 'Clostridium botulinum', ['Lactobacillus bulgaricus', 'Saccharomyces cerevisiae', 'Streptococcus thermophilus'], 'Düşük asitli (pH > 4.6) ev konservelerinde sporları 100 °C kaynar suda ölmeyebilen Clostridium botulinum, havasız kavanozda çoğalarak ölümcül botulizm toksini üretebilir; bu yüzden basınçlı konserveleme veya asitlendirme (domates/limon) hayati önem taşır.'),
  ('Karadeniz yaylalarından kış öncesi köye inilirken ahşap fıçılara (külek) basılan tuzlu yayla tereyağının külek ağzında hava ile temasını kesmek için geleneksel olarak üzerine ne kapatılır?', 'İnce kaya tuzu tabakası ve temiz tülbent/lahana veya şimşir yaprağı', ['Sıcak odun külü ve kavrulmuş fındık kabuğu', 'Tatlı üzüm pekmezi ve dövülmüş ceviz içi', 'Çiğ yumurta sarısı ve buğday kepeği'], 'Ladin veya köknar ağacından yapılan küleklere hava boşluğu kalmadan basılan yayla tereyağının üstü tuzlu salamura beziyle örtülerek oksidasyon engellenir.'),
  ('Güneydoğu Anadolu\'da (Mardin, Diyarbakır, Siirt) bağ bozumunda üzüm şırasının pekmez toprağıyla kestirilip kaynatıldıktan sonra içine buğday/dövme veya bulgur katılarak kalıplar halinde kurutulan kışlık tatlısına ne ad verilir?', 'Kesp', ['Bici bici muhallebisi', 'Tuzlu çorti turşusu', 'Ekşili bumbar dolması'], 'Şıra mevsiminde üzüm pekmeziyle kırık buğday, susam ve cevizin kaynatılıp dondurularak kurutulmasıyla elde edilen kesp/bulamaç, kışın dilimlenerek tüketilen köklü bir bağ ürünüdür.'),
  ('Bitlis ve Muş mutfağında beyaz lahana yapraklarının iri doğranıp reyhan, kırmızı biber ve ekşi hamur mayasıyla küplere basılarak hazırlanan, kışın kemikli etle (çorti aşı / çorti taplaması) pişirilen fermente kışlık ürün hangisidir?', 'Çorti', ['Sübye', 'Kakaç', 'Somata'], 'Bitlis ve Muş yöresinin ünlü kış hazırlığı olan çorti, baharatlı fermente lahana turşusudur; kış aylarında dövme, nohut veya bulgur köfteleriyle sıcak yemeklerde kullanılır.'),
  ('Hatay ve Kilis mutfaklarında yeşil mercimek, patlıcan, nohut ve sarımsağın nar ekşisi veya sumak suyuyla ağır ateşte pişirildiği, et içermemesine rağmen çok doyurucu olan tarihsel yemek hangisidir?', 'Şeyhülmualla', ['Kuzu incik ve arpacık soğanla yapılan papaz yahnisi', 'Pirinç ve kuru üzümle doldurulan zeytinyağlı lahana sarması', 'Nohut ve kemikli etle güveçte kaynatılan İspir fasulyesi'], '\'Dolmaların/yemeklerin piri\' anlamına gelen şeyhülmualla, kızartılmadan çiğden veya hafif közlenerek katmanlanan patlıcanların yeşil mercimek ve nar ekşisiyle pişirildiği köklü bir yemektir.'),
  ('Kastamonu\'nun Devrekâni ve merkez köylerinde hindi veya tavuk suyuna batırılmış rulo kuru yufka dilimlerinin tepsiye dizilip üzerine eritilmiş tereyağı ve bol dövülmüş ceviz dökülmesiyle hazırlanan tescilli yemek hangisidir?', 'Banduma', ['Ekşili hamur ve kıymayla sarılan biryan mantısı', 'Siyez bulguru ve ekşi ayranla kaynatılan tarhana', 'Mısır unu ve karalahana yaprağıyla bağlanan malak'], 'Kastamonu\'da \'serme\' adı verilen ince yufkalar rulo yapılıp kesilir, sıcak hindi suyuna bandırılarak (\'banduma\') tepsiye kat kat dizilir, aralarına tereyağı, ceviz ve didiklenmiş hindi eti konulur.'),
  ('Çorum\'un İskilip ilçesinde düğünlerde dev bakır kazanlar içinde suyun buharına değmeden ahşap çatal (\'cağ\') üzerindeki bez torbada yaklaşık on iki saat terletilerek pişirilen tarihi pilavlı et yemeği hangisidir?', 'İskilip dolması', ['Asma yaprağına kemikli kaburga dizilen Tokat dolması', 'Kurutulmuş patlıcan ve biberle yapılan Antep dolması', 'Kuzu işkembesine nohut ve pirinç doldurulan şırdan'], 'Adında \'dolma\' geçmesinin nedeni Akçeltik pirincinin bez torba (\'cağ torbası\') içine doldurulup altta pişen sığır etinin ve soğanın aromalı buharıyla saatlerce demlenmesidir.'),
  ('Antalya ve Alanya mutfağında tahin, limon suyu, ezilmiş sarımsak, kimyon ve kırmızı toz biberin ılık suyla krema kıvamına gelene dek çırpılmasıyla yapılan meze ve ekmek üstü sos hangisidir?', 'Hibeş', ['Nohut püresiyle hazırlanan Antakya humusu', 'Köz patlıcan ve yoğurtla yapılan babagannuş', 'Ceviz ve bayat ekmekle dövülen Çerkez tavuğu'], 'Akdeniz\'in köklü susam kültürünün ürünü olan Antalya hibeşi, tahinin limon ve suyla kesilip tekrar bağlanması tekniğine dayanır; hem soğuk meze hem makarna-sebze sosu olarak tüketilir.'),
  ('Isparta mutfağında bakır tavalarda kaburga ve kol etleriyle bir bütün halinde ağır odun ateşinde pişirilen, piştikten sonra derisi nar gibi kızarmış etlerin salkım üzümle birlikte sunulduğu ünlü kebap hangisidir?', 'Isparta fırın (tandır) kebabı', ['Süt ve soğan suyunda marine edilen çöp şiş', 'Kavanoz içinde buharda pişirilen kuzu güveç', 'Köz patlıcan yatağında sunulan abant kebabı'], 'Isparta kebabı saatlerce kendi yağında piştiği için ağır gelmemesi ve sindirimi rahatlatması amacıyla geleneksel olarak yanında mevsiminde taze yeşil üzüm salkımı ve pideyle servis edilir.'),
  ('Tokat ve Amasya mutfağında kuru iç baklanın kuzu kemikli et veya pastırmayla kazanda, asma yaprağına sarılmış ince bulgurlu dolmaların üstünde ya da bir arada ağır ateşte pişirildiği ünlü yöresel yemek hangisidir?', 'Bakla dolması', ['Zeytinyağı ve dereotuyla ezilerek kalıplanan fava', 'Taze yeşil bakla kabuklarıyla pişirilen yoğurtlu borani', 'Kuru fasulye ve mısır unuyla bağlanan karalahana sarması'], 'Tokat ve Amasya\'nın düğün ve bayram sofralarında başköşede yer alan etli bakla dolmasında harca kırılmış kuru iç bakla ve ince bulgur konur, tencere tabanına ise kaburga kemikleri dizilir.'),
  ('Mardin mutfağında haşlama içli köfteye \'ikbebet\' denilirken, dışı pirinç-bulgur-et karışımından yoğrulup yassı daire biçiminde kapatılarak önce haşlanıp sonra yumurtaya bulanarak kızartılan içli köfte çeşidine ne ad verilir?', 'İrok', ['Kuzu işkembesiyle dikilip haşlanan kibe dolması', 'Pekmez ve erik kurusuyla pişirilen alluciye aşı', 'Kişniş ve sumakla fırınlanan Mardin sembuseği'], 'Mardin\'in tescilli lezzetlerinden irok, tekerlek gibi yassı yuvarlak formda kapatılır, kişnişli kıymalı harç taşır ve yumurtalı kaplamayla kızartılarak ikbebetten ayrılır.'),
  ('Malatya mutfağında kiraz, asma, dut veya fasulye yapraklarının serçe parmağı inceliğinde minik kalemler halinde nohut-bulgur kırmasıyla sarılıp ekşili erik sosu ve süzme yoğurtla sunulduğu ünlü sarma hangisidir?', 'Kiraz yaprağı sarması', ['Pirinç, kuş üzümü ve tarçınla sarılan İstanbul zeytinyağlı yaprak dolması', 'Mısır yarması ve kuyruk yağıyla kalın sarılan Karadeniz lahana dolması', 'Kıyma ve domates salçasıyla bütün pişirilen kabak çiçeği sarması'], 'Malatya mutfak inceliğinin zirvesi sayılan kiraz yaprağı sarmasında (avrat köftesi de denir) harçta pirinç yerine yarma buğday kırığı kullanılır; yoğurtlu ve erik ekşili karamelize soğan sosuyla birleştirilir.'),
  ('Van ve Hakkâri mutfağında dana veya kuzu etinin ince bulgur, nohut, pirinç ve kurutulmuş erik/kayısı ile çömlekte saatlerce kaynatılıp şölen yemeği olarak sunulduğu geleneksel aş hangisidir?', 'Keledoş', ['Taze kabak ve cevizle kavrulan murtuğa', 'Süzme yoğurt ve mısır unuyla yapılan kuymak', 'Patlıcan ve biberle fırınlanan türlü güveç'], 'Van\'ın coğrafi işaretli en meşhur kış ve bayram yemeği olan keledoş; kavurma et, nohut, yeşil mercimek, dövme buğday, ak pancar otu ve ezilmiş kurutun (kurutulmuş ayran süzmesi) birleşimiyle pişirilir.'),
  ('Afyonkarahisar mutfağında düğün ve sıra yemeklerinin değişmez lezzeti olan \'çullama köfte\'ye adını veren dış kaplama işlemi nedir?', 'Yoğrulup haşlanan bulgurlu et köftelerinin un, yumurta ve yoğurtlu bulamaca (\'çul\') batırılarak yağda kızartılması', ['Köftelerin ince açılmış baklava yufkasına tek tek sarılıp fırında şerbetlenerek pişirilmesi', 'Çiğ kıymanın asma yapraklarıyla tamamen örtülüp kömür korunun altına gömülmesi', 'Haşlanmış köftelerin dövülmüş ceviz ve haşhaş tozuna bulanarak soğuk servis edilmesi'], 'Afyon çullama köftesinde ince bulgur ve kıymayla yapılan köfteler önce haşlanır, ardından yumurtalı-unlu karışıma (\'çullama\' harcı) batırılıp kızartılarak dışı yumuşak kabuklu hale getirilir.'),
  ('Kütahya mutfağında çok küçük kareler halinde kesilip dört ucu ortada birleştirilen hamurların içinde kıyma bulunmamasına rağmen mercimek veya nohutla pişirilip sarımsaklı yoğurtla sunulduğu coğrafi işaretli yemek hangisidir?', 'Kütahya cimcik aşı', ['Kuzu eti ve arpa şehriyeyle fırınlanan güveç pilavı', 'Haşhaş ezmesi ve cevizle katlanan tahinli gözleme', 'Kurutulmuş elma dilimleri ve etle pişirilen hoşaf yahnisi'], 'Kütahya mutfağında hamurun parmak ucuyla \'cimciklenerek\' kapatıldığı etsiz hamur yemeğine cimcik; ince bulgur ve tarhanadan minik toplar yuvarlanarak yapılan çorbaya ise sıkıcık çorbası denir.'),
  ('Balıkesir ve Çanakkale düğün sofralarının baş yemeği olan \'sura\', kuzu veya oğlağın hangi bölümünün baharatlı iç pilavla doldurulup bakır tepside ağır fırın ateşinde pişirilmesiyle yapılır?', 'Ön kol ve kaburga kafesi', ['Temizlenmiş kalın bağırsak ve işkembe kesesi', 'Arka but kemikleri sıyrılmış incik yuvası', 'Boyun omurları çıkarılmış gerdan halkası'], 'Batı Anadolu (özellikle Balıkesir, İzmir-Bergama ve Manisa) mutfağında Hıdrellez ve düğün yemeği olan kuzu/oğlak surası, kaburga ve kol altındaki zarın cep gibi açılıp ciğerli-çam fıstıklı pilavla doldurulmasıyla fırınlanır.'),
  ('Balıkesir\'in coğrafi işaretli \'tirit\' ve düğün çorbası geleneğinin yanında yer alan \'keşkek\'ten farklı olarak, tavuk eti, nohut ve ev yapımı ince yufka kırıntılarının tavuk suyuyla kat kat ıslatılıp cevizle sunulduğu yöresel yemek hangisidir?', 'Balıkesir tavuklu mantısı', ['Kıyma ve soğanla kapatılıp suda haşlanan Kayseri mantısı', 'Pirinç ve dereotuyla sarılan zeytinyağlı pazı dolması', 'Mercimek ve bulgurla yoğrulan ekşili marul kısırı'], 'Balıkesir saçaklı mantısında hamur kapatılmaz ya da ince şeritler (erişte/saçak) halinde kesilip fırında kızartılır; tavuk suyuyla demlendirilip üzerine didiklenmiş tavuk ve sarımsaklı yoğurt konulur.'),
  ('Karaman ve Mersin\'in Toros eteklerindeki ilçelerinde (Ermenek, Mut, Bozkır) kavrulmuş susam, ceviz veya yer fıstığının ince bulgur, tahin, domates ve salçayla soğuk su eklenerek sulandırıldığı yaz yemeği hangisidir?', 'Batırık', ['Sıcak kemik suyu ve kavurmayla pişirilen tutmaç', 'Fırında patates ve beşamel sosla kızartılan oturtma', 'Haşlanmış buğday ve şekerle soğutulan koliva'], 'Toroslar\'ın en özgün soğuk bulgur yemeklerinden olan batırık; kavrulmuş susam ve cevizin dövülüp ince bulgurla yoğrulmasıyla hem kuru köfte (\'sıkma\') olarak hem de soğuk domatesli-ekşili suyla açılarak haşlanmış lahanayla kaşıklanır.'),
  ('Ordu ve Giresun mutfağının zengin vejetaryen yayla ve orman florasını yansıtan yemeklerinden \'sakarca mıhlaması / kavurması\', ilkbaharda toplanan hangi bitki grubundan yapılır?', 'Beyaz çiçekli yabani soğanımsı bahar otu', ['Deniz kıyısındaki kayalıklarda yetişen tuzlu su yosunu', 'Meşe ağaçlarının köklerinde büyüyen siyah toprak mantarı', 'Fındık bahçelerinde budanan kurumuş odunsu sürgün kabuğu'], 'Karadeniz\'de kar kalkarken fındık altlarında çıkan sakarca (Ornithogalum), haşlanıp acı suyu süzüldükten sonra soğan, mısır unu ve yumurtayla kavrularak çok sevilen bir bahar yemeğine dönüşür.'),
  ('Trakya ve Balkan göçmen mutfağında (Edirne, Kırklareli, Bursa) Hıdrellez ve düğün sofraları için kuzu ciğeri, pirinç, çam fıstığı, kuş üzümü ve taze naneden yapılan iç pilavın hangi doğal zar içine sarılarak fırınlandığı yemek \'ciğer sarması\' adını alır?', 'Kuzunun gömleği', ['Salamura edilmiş geniş asma veya karalahana yaprağı', 'Nişasta ve sütle açılmış ince baklavalık yufka yaprağı', 'Temizlenip tuzlanmış kalın sığır bağırsağı kılıfı'], 'Gömlek yağı (omentum) sıcak suda yumuşatılıp kâseye yayılır, içine baharatlı ciğerli pilav doldurulup bohça gibi kapatılır; fırında yağ eridikçe sarmaya nar gibi kızarmış bir dış kabuk kazandırır.'),
  ('Rize ve Artvin yöresinde sonbaharda olgunlaşan kokulu siyah üzümün (İsabella / kokulu kara üzüm) şırasının mısır unu veya nişastayla pişirilmesiyle yapılan mor renkli muhallebi tatlısı hangisidir?', 'Pepeçura', ['Kuru incir ve cevizle pişirilen incir dondurması', 'Fırınlanmış mısır unu ve pekmezle yapılan herle', 'Süt ve kabak dilimleriyle kaynatılan sütlü kabak'], 'Doğu Karadeniz\'in kendine özgü çileksi kokulu siyah üzümünden elde edilen mor şıranın mısır unuyla bağlanıp soğutulmasıyla yapılan pepeçura, coğrafi işaretli geleneksel bir meyve peltesidir.'),
  ('Kayseri mutfağının coğrafi işaretli bayram ve gelin tatlısı \'nevzine\'ye hem esmer rengini hem de ağızda dağılan kıyır dokusunu kazandıran karakteristik üçlü hangisidir?', 'Tahin, üzüm pekmezi ve ceviz içi', ['Süzme bal, boz Antep fıstığı ve gül suyu', 'Haşhaş ezmesi, pancar şekeri ve fındık kırığı', 'Manda kaymağı, hindistancevizi ve limon kabuğu'], 'Kayseri nevzine tatlısında tahin, tereyağı, süt/yoğurt ve cevizle yoğrulan tok hamur tepsiye basılıp fırınlanır; şerbetinde ise mutlaka üzüm pekmezi bulunduğu için kendine özgü esmer rengini ve tadını alır.'),
  ('Edirne\'de II. Murat ve Fatih dönemlerinden kalma saray helvahanesi geleneğinin devamı olarak 41 çeşit baharat, bal ve yumurta akıyla yapılan coğrafi işaretli helva hangisidir?', 'Deva-i misk helvası', ['Susam tahini ve çöven suyuyla yapılan yaz helvası', 'Un ve tereyağının tel tel çekilmesiyle yapılan pişmaniye', 'İrmik ve çam fıstığının sütle demlendiği saray helvası'], 'Misk, tarçın, karanfil, zencefil, kakule ve safran gibi kırk bir baharatla hazırlanan Edirne deva-i misk helvası, Osmanlı şifahanelerinde güç verici macun-tatlı olarak doğmuştur.'),
  ('Osmanlı yeniçeri törenlerinde askerlerin sadrazama bağlılıklarını bildirmek amacıyla sundukları, adını \'akit\' (sözleşme/bağlılık) kökünden alan parlak ve sert geleneksel şekerleme hangisidir?', 'Akide şekeri', ['Kızamık otuyla renklendirilen lohusa şekeri', 'Badem içi kaplanarak parlatılan badem şekeri', 'Susam ve pekmezle dondurulan krokan helvası'], 'Ulufe divanında yeniçerilerin pişirip devlet erkânına sunduğu sert kaynatılmış tarçınlı, karanfilli, bergamotlu veya güllü şeker, karşılıklı sadakat sözleşmesini (\'akit\') simgelediği için akide adını almıştır.'),
  ('Eskişehir mutfağında yaklaşık iki-üç santimetre çapında kısa silindir çubuklar halinde kesilen ve adını geleneksel çelik-çomak oyunundaki kısa değnekten alan coğrafi işaretli helva hangisidir?', 'Met helvası', ['Cevizli ve üzüm pekmezli Kütahya köpük helvası', 'Pirinç unu ve safranla kavrulan saray reşidiyesi', 'Fırında kaşar peyniri gibi kızartılan balıkçı helvası'], 'Un, yağ, şeker, limon ve suyla çekilerek hazırlanan Eskişehir met helvası, uzun rulo yapılıp oyun çubuğu (\'met\') şeklinde kesilmesiyle tanınır.'),
  ('Bilecik, Kütahya, Eskişehir ve Sakarya (Taraklı) hattında çöven kökü suyunun şeker şurubuyla büyük kazanlarda saatlerce çırpılmasıyla üretilen, kaşıkla yenilen yarı akışkan bembeyaz helva hangisidir?', 'Köpük helvası', ['Fırınlanmış tuzsuz peynir ve irmikle yapılan höşmerim', 'İki ince gofret yaprağı arasına sürülen kağıt helva', 'Pekmez ve unun tereyağında kavrulduğu aside helvası'], 'Taraklı ve Kütahya-Bilecik yöresinde özellikle kış ve panayır lezzeti olan köpük helvası, tahin içermeden çöven suyu ve şeker ağdasının dövülmesiyle krema/mereng kıvamında üretilir.'),
  ('Muğla\'nın Datça yarımadasında yörenin ünlü Nurlu ve Akbadem çeşitlerinin havanda dövülüp yumurta akı ve bal/şekerle hafifçe pişirilmesi veya kurabiyeleştirilmesi dışında, şerbetli hamur tatlısı olarak yapılan \'Datça damat tatlısı\'nın iç dolgusu nedir?', 'Kırılmış Datça bademi, tarçın ve karanfil', ['Tuzsuz künefe peyniri ve rendelenmiş portakal kabuğu', 'Haşlanmış kestane ezmesi ve kavrulmuş susam tahini', 'Kurutulmuş incir püresi ve mavi haşhaş tohumu'], 'Baklava yufkasından rulo veya bohça şeklinde yapılan Datça damat tatlısı, ceviz ya da Antep fıstığı yerine yörenin iri aromatik bademleri ve baharatlarıyla doldurulur.'),
  ('Karaman, Konya ve Aksaray yörelerinde yufka veya mayasız hamurun sac üzerinde pişirilip ufalandıktan sonra tereyağı ve pekmez/şeker şerbetiyle ovularak hazırlanan geleneksel tatlı hangisidir?', 'Omaç tatlısı', ['Süt ve orkide salebiyle dondurulan kesme dondurma', 'Kireç suyunda bekletilmiş çıtır ceviz reçeli', 'Badem ve gül suyuyla ezilen Edirne badem ezmesi'], 'Orta Anadolu\'da bayatlayan ya da taze pişirilen kuru yufkaların el ile ufalanıp kızgın tereyağı, ceviz ve pekmezle harmanlanmasıyla yapılan tatlı omaç (ovmaç), atıksız mutfağın tipik bir örneğidir.'),
  ('Gaziantep ve Kilis mutfağında özellikle kış aylarında irmik ve peynir veya kaymak kullanılarak \'cennet çamuru\' (Kilis kaymaklı künefesi) yapılırken tel kadayıf fırınlanmak yerine nasıl pişirilir?', 'İnce kıyılmış çiğ kadayıf tereyağı ve şekerle ocak üzerinde kavrularak', ['Bütün kadayıf telleri tuzlu kaynar suda haşlanıp fırın ızgarasında kurutularak', 'Kadayıf hamuru sütle ıslatılıp hiç ısı görmeden dondurucuda kalıplanarak', 'Kızgın ayçiçeği yağında derin tencerede kızartılıp pekmeze batırılarak'], 'Kilis\'in coğrafi işaretli \'cennet çamuru\' tatlısında çiğ tel kadayıf ufalanıp sade yağda kavrulur, şerbet ve bol toz boz Antep fıstığıyla yemyeşil yumuşak bir dokuya getirilip üzerinde kaymakla sunulur.'),
  ('Sarı leblebi dışında Tavşanlı (Kütahya), Denizli (Serinhisar) ve Çorum\'da üretilen, mide asidini yatıştırmasıyla bilinen \'beyaz leblebi\' (sakız leblebisi) hangi nohut tipinden ve nasıl elde edilir?', 'Küçük taneli nohudun kabuğu çatlatılıp kavrularak genleştirilmesiyle', ['Sarı leblebinin kireç kaymağı ve süt tozuna batırılarak boyanmasıyla', 'Nohutların kabuğu soyulduktan sonra şekerli beyaz çikolatayla kaplanmasıyla', 'Haşlanmış beyaz fasulyenin taş fırında kurutulup tuzlanmasıyla'], 'Beyaz leblebi boyalı değildir; sıkı dokulu küçük beyazlık/sakızlık nohut çeşidinin özel ısı ve nem dengesiyle patlatılıp kabuğunun ayrılması sonucu doğal beyaz ve gevrek bir doku oluşur.'),
  ('Antalya mutfağında ince açılmış yufkanın içine tuzsuz taze peynir veya ceviz konulup zarf gibi katlanarak sacda ya da tavada kızartıldıktan sonra sıcak bal/şerbet dökülen yöresel tatlı hangisidir?', 'Arap kadayıfı ve katmer ailesinden kıvrım / serpme börek tatlısı', ['Haşlanmış buğday ve nohutla soğuk sunulan aşure çorbası', 'Tahin ve limon suyuyla çırpılan sarımsaklı hibeş ezmesi', 'Kurutulmuş elma ve armut dilimleriyle kaynatılan kak hoşafı'], 'Antalya\'da incecik serpme börek/katmer tekniği hem peynirli-kıymalı tuzlu olarak hem de peynirli-cevizli yapılıp üzerine pudra şekeri veya bal gezdirilerek tatlı niyetine tüketilir.'),
  ('Samsun\'un Çarşamba ve Terme, Ordu\'nun Ünye ilçelerinde ince açılmış yufka katlarının fındık veya cevizle büzülüp kıvrılarak fırınlandığı yöresel şerbetli tatlı hangisidir?', 'Kıvratma', ['Kuru üzüm ve haşhaşla rulo sarılan şerbetsiz nokul', 'Mısır unu ve yoğurtla fırınlanan tuzlu mısır ekmeği', 'Kıyma ve soğanla kapalı pişirilen Karadeniz pidesi'], 'Şerbet dökülmeden yalnızca yufka katları arasına konulan toz şeker, fındık/ceviz ve tereyağının ağır fırın ısısında kıtırlaşmasıyla yapılan Çarşamba kıvratması şerbetsiz ama tatlı bir baklava akrabasıdır.'),
  ('Diyarbakır ve Mardin\'de soğuk süt, irmik ve şekerle pişirilen muhallebi katmanının üzerine tel kadayıf veya baklava yufkası kapatıldığı \'soğuk baklava\' akımından yüzyıllar önce, Hatay ve Adana\'da mısır nişastası paluzesi, dondurma ve gül suyuyla kâsede sunulan geleneksel tatlı hangisidir?', 'Haytalı', ['Sıcak peynir ve kadayıfla kızartılan künefe', 'İrmik ve çöven köpüğüyle sunulan kerebiç', 'Tahin ve pekmezle fırınlanan sıcak helva'], 'Antakya\'nın tarihi Affan Kahvesi gibi mekânlarıyla özdeşleşen haytalı; sütle pişirilmiş küp nişasta muhallebisi, gül suyu şurubu ve keçi sütlü dondurmanın serinletici buluşmasıdır.'),
  ('Elazığ mutfağında üst üste dizilen ince yufka veya taş ekmeği katlarının arasına bol dövülmüş ceviz ve eritilmiş tereyağı gezdirilip sıcak şeker şerbetiyle demlendirilen geleneksel tatlı hangisidir?', 'Taş ekmeği tatlısı', ['Kurutulmuş dut unu ve suyla yoğrulan çiğ helva', 'Süzme yoğurt ve yarmayla kaynatılan ayran aşı', 'Kıyma ve reyhanla suda haşlanan Harput köftesi'], 'Elazığ\'da sac veya sıcak taş üzerinde mayalı sulu hamurdan göz göz pişirilen krepsi yufkalara \'taş ekmeği\' denir; kat kat cevizlenip şerbetlenerek nefis bir yöresel tatlıya dönüştürülür.'),
  ('Karadeniz Ereğli, Zonguldak ve Bartın mutfağında sac üzerinde pişirilen ince kuru gözleme/yufka yapraklarının şerbet ve bol cevizle kat kat tepsiye döşenmesiyle yapılan bayram tatlısı hangisidir?', 'Beyaz baklava', ['Fırında üzeri yakılarak karamelize edilen sütlaç', 'Kavrulmuş un ve pekmezle sıcak sunulan hasuda', 'Kızgın yağda halka biçiminde pişirilen tulumba'], 'Batı Karadeniz\'de fırınlanıp kızartılmadan, sacda beyaz pişirilmiş kuru nişastalı yufkaların ceviz ve ılık şerbetle katmanlanmasına \'beyaz baklava\' (Bartın beyaz baklavası) denir.'),
  ('Şanlıurfa ve Mardin sıra gecelerinde kış akşamları tepside sıcak sunulan \'zingil\' veya \'halka/müşebbek\' tatlılarının dışında, patlıcan veya kabak kullanılmadan pekmez ve nişastayla sıcak kâsede cevizle ikram edilen pelteye Urfa\'da ne denir?', 'Şire (Bulamaç / Paluze) tatlısı', ['Kızarmış ekmek ve sütle yapılan tirileçe tatlısı', 'Tuzsuz peynir ve irmikle kavrulan Çanakkale helvası', 'Yumurta akı ve bademle kurutulan acıbadem kurabiyesi'], 'Bağ bozumu ve kış gecelerinde üzüm pekmezi veya şırasının nişastayla pişirilip üzerine sade yağ ve bol ceviz dökülmesiyle hazırlanan sıcak bulamaç/paluze Güneydoğu konukseverliğinin temel ikramlarındandır.'),
  ('Gaziantep mutfağında buğday nişastası, su ve üzüm şırası/pekmeziyle pişirilen peltenin tepsiye dökülüp kareler halinde kesilerek güneşte yarı saydam kurutulduğu çerezlik kış tatlısına ne ad verilir?', 'Muska ve dilme bastık', ['Yumurta ve sütle fırınlanan sıcak kaymaklı ekmek kadayıfı', 'İrmik ve yoğurtla kabartılan şerbetli İzmir şambalisi', 'Pirinç ve tavuk göğsüyle dövülen Osmanlı saray muhallebisi'], 'Gaziantep şıra kültüründe ince serilen pestile \'bastık\', daha kalın dökülüp baklava/kare dilim kesilerek kurutulan nişastalı pekmez lokumuna ise \'dilme\' veya fıstık sarılı \'muska\' denir.'),
  ('Kars ve Ardahan mutfağında un, tereyağı ve yumurtanın tavada ağır ateşte kavrulup üzerine bal veya toz şeker gezdirilmesiyle kahvaltıda sıcak tüketilen geleneksel tatlı-kahvaltılık hangisidir?', 'Umaç helvası', ['Süt ve nişastayla soğuk kalıplanan tavukgöğsü', 'Haşlanmış nohut ve buğdayla yapılan soğuk aşure', 'Yufka arasına peynir konularak haşlanan su böreği'], 'Kars\'ta süt veya su serpilerek ovulan un topaklarının (\'umaç\') tereyağında kavrulmasıyla umaç helvası; Van kahvaltısında ise un, yağ ve yumurtanın kavrulup balla yenmesiyle murtuğa yapılır.'),
  ('Sinop ve Bartın mutfaklarında şerbetli hamur işlerinin yanı sıra, kızgın yağda haşhaşlı veya sade kızartılan ince hamur kesiklerinin üzerine pekmez/şerbet ve ceviz dökülerek yapılan yöresel tatlılara ne ad verilir?', 'Haluj tatlısı yerine \'mamalika\' tuzludur; tatlısı ise \'Sinop katlama / puf böreği tatlısı ve Bartın kabak burması\'', ['Kuzu eti ve çiçek bamyasıyla limonlu pişirilen Konya bamya çorbası', 'Dövme buğday ve süzme yoğurtla soğuk hazırlanan Erzurum ayran aşı', 'Siyah hardal tohumu ve vişne yaprağıyla kurulan Kırklareli hardaliyesi'], 'Bartın\'ın coğrafi işaretli \'kabak burması\' tatlısında rendelenmiş bal kabağı, ceviz, şeker ve tarçın el açması ince yufkaya sarılıp tepsiye dolanarak fırınlanır ve şerbetlenir.'),
  ('Nevşehir ve Kapadokya yöresinde yumurta, yoğurt, un ve cevizle yoğrulan hamurun merdaneyle açılıp baklava dilimi kesilerek yağda kızartıldığı ve üzüm pekmezi şerbetiyle tatlandırıldığı yöresel tatlı hangisidir?', 'Dolaz ve köftür ile birlikte Kapadokya pekmezli \'aside / sızgıt tatlısı\' yerine tescilli \'Nevşehir köftürü\'', ['Manda sütü kaymağı ve vişneyle pişirilen Afyon ekmek kadayıfı', 'Boz fıstık ve sade yağla kırk kat açılan Gaziantep baklavası', 'Çöven kökü köpüğü ve irmikli kurabiyeyle sunulan Mersin kerebici'], 'Kapadokya bağcılığının coğrafi işaretli mirası olan \'Nevşehir köftürü\' (üzüm peltesi lokumu), üzüm şırasının un ve nişastayla kaynatılıp tepsilerde dondurularak dilimler halinde güneşte kurutulmasıyla yapılır.'),
  ('Konya, Isparta ve Niğde yörelerinde nişasta, un ve su/süt bulamacının bol tereyağında kavrulup üzerine bal veya pekmez gezdirilmesiyle yapılan kaşık tatlısına yörede hangi ad verilir?', 'Dolaz', ['Haşlanmış buğday ve ayranla yapılan soğuk çorba', 'Közlenmiş patlıcan ve sarımsaklı yoğurtlu alinazik', 'Asma yaprağı ve kuru baklayla sarılan Tokat dolması'], 'Yörük ve Türkmen mutfağından gelen dolaz, özellikle Isparta ve Konya çevresinde nişasta-un karışımının tereyağı ve yumurtayla pütürlü kavrulup bal ya da pekmezle sunulduğu sıcak bir enerji tatlısıdır.'),
  ('Kastamonu\'nun coğrafi işaretli \'üryani eriği\' tatlısı/hoşafı hazırlanırken adını aldığı \'üryani\' (çıplak) sözcüğü meyvenin hangi işleme özelliğinden kaynaklanır?', 'Kabuğunun tek tek elle soyulup çekirdeklisiyle güneşte beyazımsı-kehribar kurutulmasından', ['Ağaçta hiç yaprak çıkarmadan kış ortasında meyve vermesinden', 'Şeker ve un katılmadan yalnızca tuzlu suda salamura edilmesinden', 'Toprak altındaki yumrulardan sökülerek yıkanmadan tüketilmesinden'], 'Kastamonu\'da yetişen özel mürdüm benzeri ala eriklerin dış kabukları soyulduğu (\'üryan\' bırakıldığı) ve güneşte kurutulduğu için üryani eriği adını almıştır; lifçe çok zengin bir komposto/tatlı malzemesidir.'),
  ('Kars ve Ardahan platolarında üretilen \'Kars gravyeri\'nin içinde ceviz büyüklüğüne varan düzgün gözeneklerin oluşmasını sağlayan olgunlaştırma aşaması nedir?', 'Sıcak olgunlaştırma odasında propiyonik asit bakterilerinin karbondioksit gazı üretmesi', ['Peynir kalıplarına kalıplama sırasında ahşap şişlerle dışarıdan delikler açılması', 'Telemenin içine kabartma tozu ve nohut mayası katılarak taş fırında ısıtılması', 'Taze peynirin dondurucu soğuktaki kar kuyularında ani şoklamaya bırakılması'], '19. yüzyıl sonunda İsviçreli peynir ustası David Moser\'in Boğatepe (Zavot) köyünde başlattığı Kars gravyeri üretiminde, ılık mahzen evresinde propiyonik asit bakterileri laktatı işleyerek karbondioksit kabarcıkları (gözenekler) ve tatlımsı fındıksı aroma oluşturur.'),
  ('Hatay ve Samandağ yöresinde ilkbaharda yapılan taze keçi veya inek peyniri ile çökeleğin, çörek otuyla birlikte sırsız toprak testiye kat kat basılıp toprağa gömülerek olgunlaştırıldığı peynir çeşidi hangisidir?', 'Antakya carra peyniri', ['Bilecik küp loru', 'Trakya eski kaşarı', 'Muş varto tulumu'], 'Arapça testi/küp anlamındaki \'carra\' sözcüğünden adını alan Antakya carra peynirinde bir kat tuzlanmış peynir, bir kat çörek otlu çökelek toprak testiye basılır ve testi toprağa gömülerek fazla nemi çektirilir.'),
  ('Kıbrıs Türk mutfağı ile Mersin-Adana hattında yaygın olan \'hellim\' peynirinin ızgarada veya tavada yüksek ısıya maruz kaldığında eriyip dağılmadan dışı kızaracak biçimde pişmesini sağlayan üretim aşaması nedir?', 'Taze telemenin asitlik kazanmadan kendi peynir altı suyunda yüksek derecede haşlanması ve nane serpilmesi', ['Peynir harcının içine buğday unu, mısır nişastası ve yumurta akı karıştırılıp fırınlanması', 'Sütün mayalanmadan önce keçi boynuzu pekmezi ve kaya tuzuyla iki saat kaynatılması', 'Kalıplanan peynirlerin meşe külü içinde bir yıl boyunca kurutularak taşlaştırılması'], 'Hellim üretiminde pıhtı kesildikten sonra yüksek pH değerindeyken (ekşimeden) yaklaşık 90 derecelik peynir altı suyunda haşlanır; kalsiyum-kazein ağı korunduğu için ızgarada yayılmadan kızarır.'),
  ('Çorum\'un Kargı, Osmancık ve İskilip yaylalarında çiğ inek, koyun ve keçi sütlerinin karışımından elde edilen telemenin bez torbalarda defalarca preslenip küçük bez keselere basılmasıyla üretilen ünlü peynir hangisidir?', 'Kargı tulum peyniri', ['Edirne süpürge peyniri', 'Bursa dil peyniri', 'Mersin bezdirme loru'], 'Coğrafi işaretli Kargı tulum peyniri, yaylalarda 3-4 ay süren zahmetli günlük süzme ve el yoğurması sonunda bez torbalara veya deri tulumlara basılan tam yağlı, kremsi ve keskin aromalı bir peynirdir.'),
  ('Edirne beyaz peynirini Ezine peynirinden olgunlaştırma ve lezzet profili açısından ayıran tescilli özelliklerden biri aşağıdakilerden hangisidir?', 'Meriç, Tunca ve Arda nehirleri deltası florasında otlayan hayvanların sütünden şirden mayasıyla daha yumuşak ve az tuzlu yapılması', ['Yalnızca manda sütüyle üretilip içerisine bol miktarda acı kırmızı biber ve çörek otu karıştırılması', 'Teneke yerine sırsız toprak küplere kuru olarak basılıp mağaralarda iki yıl küflendirilmesi', 'Haşlanmış telemenin tel tel çekilerek meşe odunu dumanında bir hafta boyunca tütsülenmesi'], 'Trakya\'nın üç nehir ağzındaki zengin çayır otlarıyla beslenen koyun, keçi ve inek sütlerinden yapılan Edirne beyaz peyniri; sadece şirden mayası ve kaya tuzu kullanılarak pürüzsüz, parlak beyaz yapıda üretilir.'),
  ('İzmir\'in Karaburun yarımadası, Urla ve Foça kıyılarında yetişen \'Erkence\' zeytininin dalındayken hiçbir salamura ve tuzlama işlemine gerek kalmadan yenilebilir tatlılığa ulaşan özel biçimine ne ad verilir?', 'Hurma zeytini', ['Kırma yeşil zeytin', 'Çizme pembe zeytin', 'Kostikli siyah zeytin'], 'Karaburun yarımadasının deniz çiği, poyrazı ve özel mikroikliminde ağaç üzerindeki Erkence zeytinlerinde \'Phoma oleae\' mantarı doğal tatlanma başlatır; acılığı dalında kaybolan bu zeytin toplanıp hemen tuzsuz yenir.'),
  ('Geleneksel zeytinyağı işliklerinde granit değirmen taşlarında ezilen zeytin hamurunun istiflenip hidrolik veya vidalı baskı altında sıkıldığı yuvarlak örgü torbalara ne ad verilir?', 'Çul', ['Kevgir süzgeci', 'Cendere kalıbı', 'Tandır yastığı'], 'Geleneksel taş baskı sisteminde ezilen zeytin hamuru keçi kılı, kendir veya gıda lifinden örülmüş yassı yuvarlak \'çul / işkefe\' hasırlarının arasına yayılır ve üst üste dizilerek baskı altında yağı ve karasuyu süzülür.'),
  ('Ege ve Ayvalık mutfağında zeytin hasadının ilk günlerinde değirmenden çıkan henüz dinlenmemiş, bulanık görünümlü ve taze meyvemsi kokulu ilk yağa ne ad verilir?', 'Delice yağı yerine \'taze burun yağı / su üstü çiğ yağ (kavata yağı)\'', ['Posadan hekzan çözücüsüyle çekilen sanayi pirina yağı', 'Kızartma kazanlarından süzülüp ağartılan atık yağ', 'Defne meyvesiyle birlikte kaynatılan sabunluk yağ'], 'Hasat başında ilk sıkımdan alınan, filtre edilmediği için zümrüt yeşili bulanık (meyve zerrecikli) olan ve hiçbir ısıl işlem görmemiş taze zeytinyağına Ege\'de \'burun yağı\' veya \'su üstü/ilk ağız yağı\' denir.'),
  ('Aksaray, Nevşehir, Karaman ve Kayseri gibi Orta Anadolu illerinde geçmişte aydınlatmada da kullanılan, kavrulmuş keten veya Eruca (izgın) tohumlarının taş değirmenlerde ezilmesiyle üretilen geleneksel bitkisel yağ hangisidir?', 'Bezir yağı', ['Fındık yağı', 'Çiğit yağı', 'Mısır yağı'], 'Orta Anadolu\'daki tarihi bezirhanelerde keten tohumu (veya ızgın) kavrulup koca taş değirmenlerde ezilerek keskin kokulu bezir yağı çıkarılır; taze haldeyken bulgur pilavı ve eriştede de kullanılırdı.'),
  ('İzmir\'de \'gevrek\', diğer illerde \'simit\' olarak adlandırılan susamlı halka hamur işinde, İzmir gevreğini İstanbul veya Ankara simidinden ayıran \'sıcak pekmezleme\' işlemi nasıl uygulanır?', 'Şekil verilen hamurun kaynamakta olan üzüm pekmezli şerbete batırılıp ön pişirme gördükten sonra susamlanması', ['Fırından piştikten sonra çıkan sıcak simitlerin üzerine soğuk dut pekmezi ve bal fırçayla sürülmesi', 'Hamur yoğrulurken su yerine yalnızca kaynar keçiboynuzu pekmezi ve zeytinyağı kullanılması', 'Susamların pekmezle kavrulup simit fırına girmeden önce hamurun iç boşluğuna doldurulması'], 'Soğuk pekmezlemede çiğ hamur ılık pekmezli suya daldırılırken, İzmir gevreği (ve Rize/Kastamonu simit ailesi) kaynayan pekmezli kazanda saniyelerce haşlanıp nişastası jelatinize edilerek ekstra çıtır kabuk kazanır.'),
  ('Ege Bölgesi\'nde (Ödemiş, Kula, Bozdoğan, Çeşme, Alaçatı) ve Trakya\'da bayramlarda ve özel günlerde yapılan geleneksel \'nohut mayalı ekmek\'te mayayı başlatmak için kırık nohut nasıl işlenir?', 'Kırılmış nohutların ılık su, çok az tuz/şeker ve unla cam kavanozda sıcak sarılarak köpürene dek bekletilmesiyle', ['Haşlanmış nohutların ezilip süzme yoğurt ve sirkeyle buzdolabında bir hafta dondurulmasıyla', 'Kavrulmuş sarı leblebi tozunun doğrudan kuru unla karıştırılıp hiç bekletmeden fırına sürülmesiyle', 'Taze yeşil nohut yapraklarının kaynatılıp suyunun karbonatla tepkimeye sokulmasıyla'], 'Nohut tanelerinin kabuğundaki doğal bakteriler (özellikle Bacillus subtilis ve laktik bakteriler) 38-40 derece sabit sıcaklıkta unla beslenerek tatlımsı, mahlep benzeri hoş kokulu beyaz köpüklü \'tatlı maya\'yı üretir.'),
  ('Osmanlı şehir fırıncılığında ince elenmiş beyaz has undan yapılan pahalı ve yumuşak uzun saray/konak ekmeğine \'francala\' denilirken, imaretlerde halka ve medrese talebelerine dağıtılan yassı esmer ekmeğe ne ad verilirdi?', 'Fodula', ['Güllaç', 'Boyoz', 'Kumru'], 'Osmanlı vakıf aşevlerinde (imarethanelerde), Yeniçeri ocaklarında ve sarayda çalışanlara günlük istihkak olarak dağıtılan kepekli tam buğdaydan pişirilmiş besleyici yassı somunlara \'fodula\' denirdi.'),
  ('Gaziantep mutfağında tırnaklı pide, açık pide ve lahmacun fırınlarında taze peynir, yumurta, maydanoz veya zahterle kayık biçiminde hazırlanan açık pidelere yöre ağzında hangi genel ad verilir?', 'Börek (Peynirli / Zahterli Antep böreği) ve açık ekmek', ['Kuru baklava yufkası ile sarılan soğuk su muhallebisi', 'Mısır unu ve karalahana ile pileki taşında pişen çadi', 'Haşlanmış buğday ve nohutla dövülen düğün herisesi'], 'Gaziantep çarşı fırınlarında tırnaklı pidenin yanı sıra sabahları fırına peynirli, yumurtalı veya zahterli harç götürülüp açık pide hamuruna yaydırılmasına halk arasında \'peynirli börek / şekerli börek yaptırmak\' denir.'),
  ('Geleneksel kalaycılık zanaatında ısıtılan bakır kabın iç yüzeyine erimiş kalayın homojen biçimde yayılıp tutunmasını sağlamak için pamukla birlikte sürülen beyaz toz madde hangisidir?', 'Nişadır', ['Sönmemiş kireç taşı tozu', 'Kaya tuzu ve mermer unu', 'Çamaşır sodası ve tebeşir'], 'Kalaycı ustası kumla temizlediği bakır kabı ocağa tutar, üzerine nişadır tozu atarak oksit tabakasını çözer (flaks etkisi) ve eriyen kalayı pamuk yumağıyla ayna gibi parlayana dek yüzeye sıvar.'),
  ('Rize\'nin İkizdere ve Pazar çevresindeki taş ocaklarından çıkarılıp oyularak yapılan, mısır ekmeği (çadi) ve hamsili ekmek pişirmede kullanılan gözenekli doğal taş kaba ne ad verilir?', 'Pileki taşı', ['Mermer dibek taşı', 'Granit değirmen taşı', 'Çakmak kıvılcım taşı'], 'Isıya dayanıklı bazaltik-magmatik kayaçtan oyulan pileki taşı önceden ateşte kızdırılır, içine karalahana veya defne yaprağı serilip mısır ekmeği hamuru dökülür; taş fazla nemi çekerek eşsiz bir kabuk oluşturur.'),
  ('Doğu ve İç Anadolu\'da yere gömülü kilden yapılan \'tandır\' fırınlarında açılan lavaş veya tandır ekmeği hamurunu kor ateşin yandığı sıcak yan duvara eli yanmadan yapıştırmak için kullanılan bez yastığa ne ad verilir?', 'Rapata (Tandır yastığı)', ['Evreğaç (Yufka tahtası)', 'İlistir (Delikli süzgeç)', 'Peşkir (El kurulama bezi)'], 'İçi yün veya pamukla doldurulmuş yuvarlak-oval bez kalıp olan rapata (bölgeye göre badı/duvak yastığı) üzerine açılmış hamur serilir ve tandırın kızgın duvarına hızla bastırılarak yapıştırılır.'),
  ('Ordu ve Giresun kırsalında şubat-mart aylarında dere kenarlarında ve fındık bahçelerinde morumsu çiçekleriyle ilk çıkan, haşlanıp soğan, mısır unu ve yumurtayla kavrulan coğrafi işaretli bahar otu hangisidir?', 'Galdirik (Kaldirik / Hodan) otu', ['Deniz börülcesi', 'Şevketibostan', 'Arapsaçı'], 'Hodangiller familyasından etli saplı galdirik (kaldirik) otu, Karadeniz bahar mutfağında hem mısır unlu yumurtalı kavurması hem de kışlık salamura turşusu yapılarak büyük bir tutkuyla tüketilir.'),
  ('Aydın mutfağının Ramazan Bayramı sofralarında mutlaka yer alan coğrafi işaretli \'Aydın yuvarlaması\' hazırlanırken kıyma, un, yumurta ve soğandan yuvarlanan fındık büyüklüğündeki köfteler haşlanmadan önce hangi işlemden geçirilir?', 'Kızgın zeytinyağında dış yüzeyi kabuk bağlayacak şekilde kızartıldıktan sonra et suyunda nohutla pişirilir', ['Üzüm pekmezi ve susam tahinine bulandıktan sonra güneşte üç gün kurutulmaya bırakılır', 'Pirinç ununa yuvarlanıp buharda terletildikten sonra soğuk ayranın içine atılır', 'İnce açılmış baklava yufkasına tek tek sarılıp taş fırında susuz olarak gevretilir'], 'İzmir/Ege sulu köftelerinden farklı olarak Aydın yuvarlamasında içine pirinç konulmayan sıkı köfteler önce yağda kızartılır, ardından kemik suyunda haşlanmış nohutla pişirilip sarımsaklı süzme yoğurt ve biberli yağla sunulur.'),
  ('Kütahya mutfağında ince bulgur (düğü) ve tarhananın unla yoğrulup avuç içinde mercimek büyüklüğünde tek tek sıkılması ve et suyunda pişirilip sarımsaklı yoğurtla sunulmasıyla yapılan coğrafi işaretli çorba hangisidir?', 'Sıkıcık çorbası', ['Lebeniye çorbası', 'Mahluta çorbası', 'Bamya çorbası'], 'Kütahya kadınlarının komşu imecesiyle yüzlerce minik bulgur-tarhana taneciğini parmak uçlarıyla sıkıp (\'sıkıcık\') tepside hafif kavurduktan sonra kemik suyunda pişirdiği sıkıcık çorbası yörenin simgesidir.'),
  ('Hakkâri ve Şırnak yöresi mutfağında kemikli dana veya kuzu eti, nohut, aşurelik dövme buğday ve minik bulgur köftelerinin yoğurt/ayran ile ağır ateşte birlikte pişirildiği doyurucu tören yemeği hangisidir?', 'Doğaba', ['Hünkarbeğendi', 'İmam bayıldı', 'Papaz yahnisi'], 'Adı Kürtçe/Farsça \'doğ-ab\' (ayran suyu / ayran aşı) kökünden gelen Hakkâri doğabası; kemikli et, buğday ve iç yağlı köftelerin yayık ayranıyla saatlerce karıştırılarak pişirildiği zengin bir davet yemeğidir.'),
  ('Mersin\'in Silifke ve Mut ile Karaman\'ın Ermenek ilçelerini kapsayan Taşeli Yöresi\'nde kavrulmuş susam, fıstık/ceviz, tahin ve haşlanmış ince bulgurun domates-salça-limonla yoğrulup hem kuru köfte hem de soğuk sulu çorba olarak iki aşamada sunulduğu ikram hangisidir?', 'Batırık', ['Çiğ köfte', 'Mercimek köftesi', 'Fellah köftesi'], 'Orta Toroslar Yörük mutfağının baş tacı olan batırıkta kavrulmuş susam ve yer fıstığı/ceviz havanda ezilip ince bulgurla yoğrulur; önce sıkma köftesi marulla ikram edilir, kalanına soğuk ekşili su ve salatalık-lahana eklenip kâsede içilir.'),
  ('Topkapı Sarayı mutfakları içinde yalnızca padişahın şahsına ve yakın harem halkına özel, küçük porsiyonlu ve en seçkin yemeklerin pişirildiği ayrı mutfak birimine ne ad verilirdi?', 'Kuşhane mutfağı', ['Helvahane ocağı', 'Has ahır kileri', 'Simkeşhane atölyesi'], 'Başlangıçta padişah için av kuşları ve güvercin/keklik gibi narin etlerin pişirildiği yer olmasından adını alan \'Kuşhane\', zamanla hünkârın özel yemeklerinin hazırlandığı en mahrem ve titiz saray mutfağı olmuştur.'),
  ('1844 yılında basılarak Türk mutfak tarihinin matbaada basılmış ilk yemek kitabı olma unvanını kazanan ve Mehmed Kâmil tarafından kaleme alınan eser hangisidir?', 'Melceü\'t-Tabbâhîn (Aşçıların Sığınağı)', ['Dîvânu Lügâti\'t-Türk (Türk Dilleri Sözlüğü)', 'Seyahatnâme-i Evliya Çelebi', 'Kutadgu Bilig (Mutluluk Veren Bilgi)'], 'Mekteb-i Tıbbiye-i Adliye-i Şahane hocalarından Mehmed Kâmil\'in 1844\'te taşbaskı olarak yayımladığı \'Melceü\'t-Tabbâhîn\', çorbalardan kebaplara ve tatlılara 280\'den fazla Osmanlı tarifini kayıt altına alan temel kaynaktır.'),
  ('Kahramanmaraş\'ın coğrafi işaretli \'Maraş biberi\' (ve Şanlıurfa \'isot\'u) üretilirken kırmızı biberlerin güneşte kurutulduktan sonra hafif yağ ve tuzla terletilerek koyu bordo-siyaha yakın renk almasının kimyasal açıklaması nedir?', 'Isı ve nem altında biberdeki doğal şekerler ile amino asitlerin enzimatik olmayan esmerleşme (Maillard) tepkimesiyle karamelize-isli aroma üretmesi', ['Biberlerin içine siyah zeytin karasuyu ve meşe kömürü tozu katılarak dışarıdan boyanması', 'Güneş ışığının biberdeki kapsaisin maddesini parçalayarak acılığı tamamen yok etmesi', 'Kurutma bezlerinden bibere geçen pamuk liflerinin yüksek ısıda yanıp külleşmesi'], 'Urfa isotu (\'ısı ot\') ve koyu yaprak biberde kuruyan biberler örtü altında kendi ısısıyla \'terletilir\'; bu aşamada şekerler koyulaşır, keskin ham acılık yerini çikolatamsı-isli derin bir aromaya bırakır.'),
  ('Gaziantep mutfağında yalnızca ilkbahar aylarında taze yeşil sarımsak ve taze soğanın beyaz sapları kullanılarak kuzu eti, nohut ve süzme yoğurt terbiyesiyle pişirilen mevsimlik coğrafi işaretli yemek hangisidir?', 'Şiveydiz', ['Müceddere', 'Alinazik', 'Mahluta çorbası'], 'Nisan-mayıs aylarında tarladan çıkan körpe yeşil sarımsakların acılığı kalmadığı ve tatlandığı için kuzu eti, nohut ve naneli süzme yoğurtla buluştuğu şiveydiz, Antep bahar mutfağının şifa kaynağıdır.'),
  ('Bursa mutfağında kuzu kuşbaşı et, arpacık soğan ve taze bezelyenin domatesle pişirilip ters çevrilmiş kâse formunda pilav veya patates püresiyle ya da yufka bohçası içinde sunulduğu geleneksel tencere yemeği ailesinden, haşlanmış tavuk/et ve cevizle yapılan \'damat paçası\' hangi bölgenin düğün klasiğidir?', 'Trakya ve Rumeli göçmen mutfağının', ['Hakkâri ve Şırnak yüksek yayla göçer mutfağının', 'Rize ve Artvin kıyı balıkçılığı mutfağının', 'Mardin ve Midyat Süryani bağcılık mutfağının'], 'Yufka kırıntılarının tavuk suyuyla ıslatılıp üzerine sarımsaklı-sirkeli unlu yumurta terbiyesi, didiklenmiş tavuk ve biberli tereyağı döküldüğü \'damat paçası\', Balkan/Rumeli göçmenlerinin Bursa ve Trakya\'da yaşattığı baş düğün yemeğidir.'),
];
